const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>new Intl.NumberFormat('en',{maximumFractionDigits:0}).format(Number(v)||0);
const labels={building:'AC condensate',rainfall:'Rainfall runoff',community:'Community report'};
const icons={building:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M5 21V3h14v18M9 7h2m2 0h2M9 11h2m2 0h2M9 15h2m2 0h2M3 21h18"/></svg>',rainfall:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M7 15a5 5 0 1 1 1-10 6 6 0 0 1 11 3 3.5 3.5 0 0 1-1 7M8 18l-2 3m7-3-2 3m7-3-2 3"/></svg>',community:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/></svg>'};
let records=[
{id:'B-001',type:'building',name:'Al Reem office tower',latitude:24.496,longitude:54.407,value:2453,annual:895345,level:'High',description:'Commercial · 160 AC units · 10 hours/day'},
{id:'B-002',type:'building',name:'Saadiyat learning centre',latitude:24.535,longitude:54.434,value:1472,annual:537280,level:'Medium',description:'Education · 120 AC units · 8 hours/day'},
{id:'B-003',type:'building',name:'Corniche residences',latitude:24.489,longitude:54.35,value:1840,annual:671600,level:'High',description:'Residential · 100 AC units · 12 hours/day'},
{id:'B-004',type:'building',name:'Masdar community hub',latitude:24.426,longitude:54.619,value:920,annual:335800,level:'Medium',description:'Mixed use · 60 AC units · 10 hours/day'},
{id:'R-001',type:'rainfall',name:'Al Bateen catchment',latitude:24.451,longitude:54.35,value:36800,level:'High',description:'2,500 m² catchment · 18.4 mm rainfall'},
{id:'R-002',type:'rainfall',name:'Khalifa City catchment',latitude:24.424,longitude:54.567,value:22400,level:'Medium',description:'2,000 m² catchment · 16 mm rainfall'},
{id:'R-003',type:'rainfall',name:'Yas Island catchment',latitude:24.49,longitude:54.6,value:48000,level:'High',description:'4,000 m² catchment · 15 mm rainfall'},
{id:'CR-001',type:'community',name:'Water accumulation',latitude:24.465,longitude:54.38,level:'New',description:'Standing water near a landscaped area after recent rainfall.'},
{id:'CR-002',type:'community',name:'AC condensate',latitude:24.505,longitude:54.39,level:'New',description:'Air conditioning drainage could support the nearby planted area.'}
];
let mode='demo',api='http://localhost:3000',filter='all',query='',map=null,markers=null,liveError='',busy=false,lastResult=null;
try{api=localStorage.getItem('waha-api')||api;}catch{}
const demo=structuredClone(records);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function badge(level){return `<span class="badge ${level==='High'?'high':''}">${esc(level)}</span>`;}
function banner(){return `<div class="data-note"><span>${mode==='demo'?'Demo workspace · illustrative UAE sites · changes reset on refresh':'Connected to WAHA API'}</span><button class="inline-button" data-settings>${mode==='demo'?'Connect your backend':'Connection settings'}</button></div>${liveError?`<div class="error" role="alert">${esc(liveError)} <button class="inline-button" id="retry-load">Retry</button></div>`:''}`;}
function heading(kicker,title,description,action=''){return `<div class="workspace-heading"><div><h2>${title}</h2><p>${description}</p></div>${action}</div>`;}
function list(){return records.filter(r=>(filter==='all'||r.type===filter)&&`${r.name} ${r.description} ${r.id}`.toLowerCase().includes(query.toLowerCase()));}
function valueLabel(r){return r.type==='community'?'Community observation':`${fmt(r.value)} L ${r.type==='building'?'/ day':'/ rainfall event'}`;}
function card(r){return `<button class="opportunity-card" data-record="${esc(r.id)}"><div class="record-top"><span class="type-icon ${r.type}">${icons[r.type]}</span>${badge(r.level)}</div><small>${labels[r.type]} · ${esc(r.id)}</small><h3>${esc(r.name)}</h3><p>${esc(r.description||'Site opportunity')}</p><strong>${valueLabel(r)}</strong><span class="record-location">⌖ ${Number(r.latitude).toFixed(4)}, ${Number(r.longitude).toFixed(4)}</span></button>`;}
function renderExplore(){if(map){map.remove();map=null;}$('#explore').innerHTML=`<div class="workspace">${heading('DISCOVER THE OVERLOOKED','A world of water potential.','Explore the places where a little insight can make a lasting difference.', '<a class="button button-dark" href="#analyze">Analyze a site ＋</a>')}${banner()}<div class="explore-toolbar"><div class="filter-tabs" aria-label="Opportunity type">${['all','building','rainfall','community'].map(t=>`<button data-filter="${t}" class="${filter===t?'selected':''}" aria-pressed="${filter===t}">${t==='all'?'All opportunities':labels[t]}</button>`).join('')}</div><input class="search" id="search" type="search" placeholder="Search opportunities…" aria-label="Search opportunities" value="${esc(query)}"></div><div class="explorer"><aside><div class="list-header"><span id="result-count"></span><span>ABU DHABI & BEYOND</span></div><div id="opportunity-list"></div></aside><div class="map-wrap"><div id="map" aria-label="Map of water opportunities"></div><div class="map-key"><span><i class="building"></i>Condensate</span><span><i class="rainfall"></i>Rainfall</span><span><i class="community"></i>Community</span></div><div id="map-warning" hidden>Map tiles are unavailable. You can still explore the opportunity list.</div></div></div></div>`;
if(window.L){map=L.map('map',{scrollWheelZoom:false}).setView([24.477,54.455],11);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).on('tileerror',()=>{$('#map-warning').hidden=false;}).addTo(map);markers=L.layerGroup().addTo(map);setTimeout(()=>map.invalidateSize(),100);}else{$('#map').innerHTML='<div class="empty-state">Map could not load. All opportunities are available in the list.</div>';}
$('#search').addEventListener('input',e=>{query=e.target.value;updateList();});$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b);});updateList();});updateList();bindCommon();}
function updateList(){$('#result-count').textContent=`${list().length} opportunities`;$('#opportunity-list').innerHTML=list().map(card).join('')||'<div class="empty-state"><h3>No matching opportunities</h3><p>Try another search or opportunity type.</p></div>';markers?.clearLayers();list().forEach(r=>{if(map&&Number.isFinite(+r.latitude)&&Number.isFinite(+r.longitude)){L.circleMarker([r.latitude,r.longitude],{radius:9,color:'#fff',weight:3,fillColor:{building:'#08628c',rainfall:'#49a3c0',community:'#aaa47c'}[r.type],fillOpacity:1}).addTo(markers).bindPopup(`<div class="map-popup"><small>${labels[r.type]}</small><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><strong>${valueLabel(r)}</strong><p>${esc(r.level)} ${r.type==='community'?'report':'potential'}</p></div>`);}});$$('[data-record]').forEach(b=>b.onclick=()=>{const r=records.find(x=>x.id===b.dataset.record);if(map){map.flyTo([r.latitude,r.longitude],14,{duration:.8});markers.eachLayer(m=>{const p=m.getLatLng();if(p.lat===+r.latitude&&p.lng===+r.longitude)m.openPopup();});if(innerWidth<800)$('#map').scrollIntoView({behavior:'smooth',block:'center'});}else toast(`${r.name}: ${valueLabel(r)}`);});}
function renderDashboard(){const buildings=records.filter(r=>r.type==='building'),rain=records.filter(r=>r.type==='rainfall'),reports=records.filter(r=>r.type==='community'),daily=buildings.reduce((s,r)=>s+(+r.value||0),0),runoff=rain.reduce((s,r)=>s+(+r.value||0),0),high=records.filter(r=>r.level==='High');$('#dashboard').innerHTML=`<div class="workspace">${heading('THE BIGGER PICTURE','Every drop adds up.','A clear view of the resources we can begin to recover.','<a href="#explore" class="button button-outline">Explore the map</a>')}${banner()}<div class="metrics"><article><span>AC condensate potential</span><strong>${fmt(daily)}<small>L / day</small></strong><p>Across ${buildings.length} analyzed buildings</p></article><article><span>Rainfall runoff potential</span><strong>${fmt(runoff)}<small>L</small></strong><p>Total across ${rain.length} analyzed rainfall events</p></article><article><span>High-potential opportunities</span><strong>${high.length}<small>sites</small></strong><p>Ready for further investigation</p></article><article><span>Community observations</span><strong>${reports.length}<small>reports</small></strong><p>Local insights on the map</p></article></div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><h3>Opportunity mix</h3><span>${records.length} total</span></div><div class="mix-visual"><div class="donut" style="--a:${records.length?buildings.length/records.length*100:0}%;--b:${records.length?(buildings.length+rain.length)/records.length*100:0}%"><div><strong>${records.length}</strong><span>opportunities</span></div></div><div class="mix-legend">${[['building',buildings.length],['rainfall',rain.length],['community',reports.length]].map(([t,n])=>`<div><i class="${t}"></i><span>${labels[t]}</span><strong>${n}</strong></div>`).join('')}</div></div><p class="muted small">Counts by source. Daily condensate and event-based runoff are kept separate.</p></section><section class="panel annual-panel"><h3>A little each day.<br>A lot over a year.</h3><strong>${fmt(buildings.reduce((s,r)=>s+(+r.annual||(+r.value||0)*365),0))}<small>litres of estimated annual condensate</small></strong><p>Assumes the entered daily operating pattern continues for 365 days. Seasonal output will vary.</p></section></div><section class="panel priority-panel"><div class="panel-title"><div><h3>Places to start</h3><p class="muted">High-potential sites to investigate next</p></div><a href="#analyze" class="inline-button">Add an analysis ＋</a></div><div class="table-scroll"><table><thead><tr><th>Opportunity</th><th>Source</th><th>Estimated water</th><th>Potential</th></tr></thead><tbody>${high.map(r=>`<tr><td><a href="#explore">${esc(r.name)}</a><small>${esc(r.id)}</small></td><td>${labels[r.type]}</td><td>${valueLabel(r)}</td><td>${badge(r.level)}</td></tr>`).join('')||'<tr><td colspan="4">No high-potential opportunities yet. Analyze a site to get started.</td></tr>'}</tbody></table></div></section></div>`;bindCommon();}
function field(label,name,value,type='number',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`;}
function coords(){return `<div class="form-row">${field('Latitude','latitude',24.4539,'number','min="-90" max="90" step="any"')}${field('Longitude','longitude',54.3773,'number','min="-180" max="180" step="any"')}</div>`;}
function currentKind(){return new URLSearchParams(location.hash.split('?')[1]).get('kind')==='rainfall'?'rainfall':'building';}
function renderAnalyze(){const kind=currentKind();$('#analyze').innerHTML=`<div class="workspace narrow-workspace">${heading('TURN INSIGHT INTO POSSIBILITY','What could your site recover?','Start with a few details. We’ll help you see the potential.')}${banner()}<div class="analysis-grid"><section class="panel"><div class="filter-tabs analysis-tabs"><a class="${kind==='building'?'selected':''}" href="#analyze?kind=building">AC condensate</a><a class="${kind==='rainfall'?'selected':''}" href="#analyze?kind=rainfall">Rainfall runoff</a></div><form id="analysis-form"><h3>${kind==='building'?'Tell us about your building.':'Understand your catchment.'}</h3><p class="muted form-intro">${kind==='building'?'A starting point for everyday water recovery.':'Estimate runoff from a single rainfall event.'}</p>${kind==='building'?`${field('Building name','name','Building 042','text','maxlength="120"')}<label>Building type<select name="buildingType"><option>Commercial</option><option>Residential</option><option>Education</option><option>Hospitality</option><option>Mixed use</option></select></label>`:''}${coords()}${kind==='building'?`<div class="form-row">${field('Number of AC units','acUnits',120,'number','min="1" max="100000" step="1"')}${field('Operating hours / day','averageOperatingHours',10,'number','min="0.1" max="24" step="0.1"')}</div><label class="checkbox"><input type="checkbox" name="existingCondensateDrainage" checked> Existing condensate drainage</label><label class="checkbox"><input type="checkbox" name="landscaping" checked> Landscaping on site</label>`:`${field('Rainfall depth (mm)','rainfallMm',18.4,'number','min="0.01" max="2000" step="any"')}${field('Catchment area (m²)','catchmentAreaM2',2500,'number','min="1" max="1000000000" step="any"')}${field('Runoff coefficient (0–1)','runoffCoefficient',0.8,'number','min="0" max="1" step="0.01"')}<p class="field-help">The fraction of rainfall that becomes runoff. Impervious surfaces usually have higher values.</p>`}<div id="analysis-error" class="error" role="alert" hidden></div><button class="button button-dark full-width" type="submit">Calculate water potential</button></form></section><aside id="analysis-result" class="result-panel"><div class="result-empty"><span class="result-symbol">${icons[kind]}</span><h3>Small details.<br>Meaningful insights.</h3><p>Your estimate will appear here, with potential uses and the assumptions behind it.</p><div class="formula">${kind==='building'?'AC units × operating hours × generation rate':'Rainfall (mm) × area (m²) × runoff coefficient'}</div></div></aside></div></div>`;$('#analysis-form').onsubmit=submitAnalysis;bindCommon();}
async function request(path,options={}){let res;try{res=await fetch(api.replace(/\/$/,'')+path,{...options,headers:{'Content-Type':'application/json',...options.headers},signal:AbortSignal.timeout(10000)});}catch{throw new Error('Could not reach the API. Check the server address and its CORS settings.');}let data;try{data=await res.json();}catch{throw new Error('The API returned an unreadable response.');}if(!res.ok)throw new Error(data.message||data.error||`Request failed (${res.status}).`);return data;}
async function submitAnalysis(event){event.preventDefault();if(busy)return;const form=event.currentTarget,kind=currentKind(),fd=new FormData(form),payload=Object.fromEntries(fd);for(const key of ['latitude','longitude','acUnits','averageOperatingHours','rainfallMm','catchmentAreaM2','runoffCoefficient'])if(key in payload)payload[key]=Number(payload[key]);if(kind==='building'){payload.existingCondensateDrainage=fd.has('existingCondensateDrainage');payload.landscaping=fd.has('landscaping');payload.name=payload.name.trim();if(!payload.name){$('#analysis-error').hidden=false;$('#analysis-error').textContent='Please enter a building name.';return;}}busy=true;const button=form.querySelector('button[type=submit]');button.disabled=true;button.textContent='Calculating…';$('#analysis-error').hidden=true;try{let result;if(mode==='live')result=await request(`/api/${kind==='building'?'buildings':'rainfall'}/analyze`,{method:'POST',body:JSON.stringify(payload)});else{const value=kind==='building'?Math.round(payload.acUnits*payload.averageOperatingHours*(23/15)):Math.round(payload.rainfallMm*payload.catchmentAreaM2*payload.runoffCoefficient);result={id:`${kind==='building'?'B':'R'}-${Date.now().toString().slice(-6)}`,estimatedCondensateLitresPerDay:kind==='building'?value:undefined,estimatedAnnualLitres:kind==='building'?value*365:undefined,estimatedRunoffLitres:kind==='rainfall'?value:undefined,recoveryPotential:value>=1500?'High':value>=500?'Medium':'Low',opportunityLevel:value>=30000?'High':value>=10000?'Medium':'Low',confidence:'Medium',potentialUses:payload.landscaping?['On-site landscape irrigation','Non-potable cleaning and flushing']:['Landscape irrigation','Non-potable facility applications'],assumptions:kind==='building'?['Prototype assumption: approximately 1.53 litres per AC unit per operating hour.','Annual estimate assumes 365 days at the entered operating pattern.','Actual yield varies with humidity, temperature, HVAC capacity and load.']:undefined,notes:kind==='rainfall'?['Runoff litres = rainfall in mm × catchment area in m² × runoff coefficient.','Actual capture depends on drainage, slope and available storage.']:undefined};}
const r={id:result.id,type:kind,name:kind==='building'?payload.name:`Catchment ${result.id}`,latitude:payload.latitude,longitude:payload.longitude,value:kind==='building'?result.estimatedCondensateLitresPerDay:result.estimatedRunoffLitres,annual:result.estimatedAnnualLitres,level:kind==='building'?result.recoveryPotential:result.opportunityLevel,description:kind==='building'?`${payload.buildingType} · ${payload.acUnits} AC units · ${payload.averageOperatingHours} hours/day`:`${fmt(payload.catchmentAreaM2)} m² catchment · ${payload.rainfallMm} mm rainfall`};if(!Number.isFinite(+r.value))throw new Error('The API response did not contain the expected estimate.');records.push(r);lastResult=r;$('#analysis-result').innerHTML=`<div class="result-content"><div class="result-top">${badge(r.level||'Unrated')}<span>${esc(result.confidence||'Unspecified')} confidence</span></div><strong class="result-value">${fmt(r.value)}<small>litres ${kind==='building'?'per day':'per rainfall event'}</small></strong>${kind==='building'?`<div class="annual-result"><span>Estimated annual recovery</span><strong>${fmt(result.estimatedAnnualLitres)} L</strong></div>`:''}<h3>${kind==='building'?'Put it to good use.':'A resource worth exploring.'}</h3>${kind==='building'?`<ul>${(result.potentialUses||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>Investigate suitable storage and local non-potable applications with a site specialist.</p>'}<details open><summary>Assumptions & methodology</summary><ul>${(result.assumptions||result.notes||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${mode==='demo'?'<p>Demo potential bands are illustrative thresholds, not a validated engineering rating.</p>':''}</details><p class="result-notice">Preliminary estimate. Water quality and site feasibility need assessment before reuse.</p><a class="button button-dark full-width" href="#explore">View opportunities on the map</a><small class="saved-note">${mode==='demo'?'Added to this demo session':'Saved to your backend'} · ${esc(r.id)}</small></div>`;toast('Analysis complete. Opportunity added to the map.');if(innerWidth<800)$('#analysis-result').scrollIntoView({behavior:'smooth'});}catch(e){$('#analysis-error').hidden=false;$('#analysis-error').textContent=e.message;}finally{busy=false;button.disabled=false;button.textContent='Calculate water potential';}}
function renderCommunity(){const reports=records.filter(r=>r.type==='community');$('#community').innerHTML=`<div class="workspace">${heading('LOCAL KNOWLEDGE. SHARED POSSIBILITY.','Notice something? Make it count.','Help reveal the water opportunities in your neighbourhood.')}${banner()}<div class="community-grid"><section class="panel"><h3>Share an observation</h3><p class="muted form-intro">A small observation can be the start of something useful.</p><form id="report-form"><label>What did you notice?<select name="type"><option>Water accumulation</option><option>AC condensate</option><option>Potential runoff capture</option><option>Other water opportunity</option></select></label>${coords()}<label>Tell us more<textarea name="description" rows="4" required minlength="10" maxlength="2000" placeholder="Describe what you observed and where it is…"></textarea></label><label>Photo URL <span class="optional">optional</span><input name="photoUrl" type="url" placeholder="https://…"></label><p class="field-help">Use a publicly accessible image link. No file upload is required.</p><div class="error" id="report-error" hidden role="alert"></div><button class="button button-dark full-width" type="submit">Submit observation</button><p class="field-help">${mode==='demo'?'Demo reports stay in this session and reset on refresh.':'Reports are sent to your connected WAHA backend.'}</p></form></section><section><div class="panel-title"><h3>Community observations</h3><span>${reports.length} reports</span></div><div class="report-list">${reports.map(r=>`<article class="report-card"><div class="report-heading"><span class="type-icon community">${icons.community}</span>${badge(r.level||'New')}</div><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><div class="report-meta"><span>⌖ ${(+r.latitude).toFixed(4)}, ${(+r.longitude).toFixed(4)}</span><span>${esc(r.id)}</span></div></article>`).join('')||'<div class="empty-state">No reports yet. Share the first observation.</div>'}</div></section></div></div>`;$('#report-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const form=e.currentTarget,fd=new FormData(form),payload={latitude:Number(fd.get('latitude')),longitude:Number(fd.get('longitude')),type:fd.get('type'),description:String(fd.get('description')).trim(),photoUrl:fd.get('photoUrl')||null};if(payload.description.length<10){$('#report-error').textContent='Please describe your observation in at least 10 characters.';$('#report-error').hidden=false;return;}busy=true;const b=form.querySelector('button[type=submit]');b.disabled=true;b.textContent='Submitting…';try{const result=mode==='live'?await request('/api/community/reports',{method:'POST',body:JSON.stringify(payload)}):{id:`CR-${Date.now().toString().slice(-6)}`,status:'New'};records.unshift({id:result.id,type:'community',name:payload.type,latitude:payload.latitude,longitude:payload.longitude,description:payload.description,level:result.status||'New'});renderCommunity();toast(mode==='demo'?'Observation added to this demo session.':'Observation submitted successfully.');}catch(err){$('#report-error').hidden=false;$('#report-error').textContent=err.message;b.disabled=false;b.textContent='Submit observation';}finally{busy=false;}};bindCommon();}
function normalize(raw,type){const b=raw.building||{},p=raw.properties||{},loc=raw.location||{};return {id:raw.id||p.id||`${type}-${Math.random().toString(36).slice(2,8)}`,type,name:raw.name||b.name||raw.title||p.name||(type==='community'?raw.type:null)||`${labels[type]} opportunity`,latitude:raw.latitude??b.latitude??loc.latitude??p.latitude,longitude:raw.longitude??b.longitude??loc.longitude??p.longitude,value:raw.estimatedCondensateLitresPerDay??raw.estimatedRunoffLitres??raw.estimatedLitres??raw.value,annual:raw.estimatedAnnualLitres,level:raw.recoveryPotential||raw.opportunityLevel||raw.status||raw.priority||'Unrated',description:raw.description||raw.notes?.[0]||raw.buildingType||labels[type]};}
function unwrap(data){if(Array.isArray(data))return data;for(const k of ['opportunities','reports','data','buildings','rainfall']){if(Array.isArray(data[k]))return data[k];}throw new Error('Unexpected list format from the API. Expected an array or an opportunities/reports/data array.');}
async function loadLive(){liveError='';try{const [b,r,c]=await Promise.all([request('/api/buildings/opportunities'),request('/api/rainfall/opportunities'),request('/api/community/reports')]);records=[...unwrap(b).map(x=>normalize(x,'building')),...unwrap(r).map(x=>normalize(x,'rainfall')),...unwrap(c).map(x=>normalize(x,'community'))];}catch(e){liveError=e.message;}route(false);}
function bindCommon(){$$('[data-settings]').forEach(b=>b.onclick=openSettings);if($('#retry-load'))$('#retry-load').onclick=loadLive;$('#connection-button').textContent=mode==='demo'?'Demo data · API settings':'Live API · Settings';}
function openSettings(){const dialog=$('#settings-dialog');dialog.innerHTML=`<form id="connection-form"><div class="dialog-heading"><h3>Connect WAHA</h3><button type="button" class="close-dialog" aria-label="Close settings">×</button></div><p class="muted">Explore with sample data or connect the frontend to your WAHA backend.</p><label>Backend base URL<input id="api-url" type="url" value="${esc(api)}" required placeholder="http://localhost:3000"></label><p class="field-help">Use the server origin, without /api. The backend must allow this page’s origin in its CORS configuration.</p><div class="error" id="connection-error" role="alert" hidden></div><button class="button button-dark full-width" type="submit">Test & connect</button><button class="button button-outline full-width" type="button" id="use-demo">Use demo workspace</button><p class="field-help">An HTTPS hosted frontend needs an HTTPS backend. For localhost:3000, run this frontend locally on port 5173.</p></form>`;dialog.showModal();$('.close-dialog').onclick=()=>dialog.close();$('#use-demo').onclick=()=>{mode='demo';liveError='';records=structuredClone(demo);dialog.close();route(false);toast('Demo workspace restored.');};$('#connection-form').onsubmit=async e=>{e.preventDefault();const candidate=$('#api-url').value.trim().replace(/\/$/,'');const url=new URL(candidate);if(!['http:','https:'].includes(url.protocol)||url.username||url.password){$('#connection-error').hidden=false;$('#connection-error').textContent='Enter an HTTP or HTTPS server URL without credentials.';return;}if(location.protocol==='https:'&&url.protocol==='http:'){$('#connection-error').hidden=false;$('#connection-error').textContent='Use an HTTPS backend here, or run the frontend locally for an HTTP backend.';return;}const previous=api;api=candidate;const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;button.textContent='Connecting…';try{await request('/api/health');mode='live';records=[];try{localStorage.setItem('waha-api',api);}catch{}await loadLive();dialog.close();toast(liveError?'Connected, but opportunity data could not load.':'Connected to WAHA backend.');}catch(err){api=previous;$('#connection-error').hidden=false;$('#connection-error').textContent=err.message;}finally{button.disabled=false;button.textContent='Test & connect';}};}
function route(scroll=true){const id=(location.hash||'#home').slice(1).split('?')[0];if(id==='connection'){openSettings();return;}if(['possibilities','how-it-works'].includes(id)){if(!$('#home').classList.contains('active')){$$('.page').forEach(p=>p.classList.toggle('active',p.id==='home'));}setTimeout(()=>document.getElementById(id).scrollIntoView({behavior:'smooth'}),30);return;}const page=['home','explore','dashboard','analyze','community'].includes(id)?id:'home';$$('.page').forEach(p=>p.classList.toggle('active',p.id===page));$$('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===page));document.body.classList.toggle('on-home',page==='home');window.dispatchEvent(new CustomEvent('waha:route',{detail:page}));$('nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');if(page==='explore')renderExplore();if(page==='dashboard')renderDashboard();if(page==='analyze')renderAnalyze();if(page==='community')renderCommunity();if(scroll)window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>route());$('.menu-toggle').onclick=()=>{const nav=$('nav');nav.classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',nav.classList.contains('open'));};$('#connection-button').onclick=e=>{e.preventDefault();openSettings();};route();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'list_water_opportunities',title:'List water opportunities',description:'Read opportunities currently loaded in the WAHA workspace, optionally filtered by source.',inputSchema:{type:'object',properties:{type:{type:'string',enum:['all','building','rainfall','community']}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:({type='all'}={})=>{if(!['all','building','rainfall','community'].includes(type))throw new Error('Unknown opportunity type');return {mode,opportunities:records.filter(r=>type==='all'||r.type===type)};}});}catch{}}
